SHEET_DATA["Данные взрослой матрицы"].formulas["J407"] = function(SHEET, cell, rangeVals) { return fn_CONCATENATE(cell(SHEET, "F407"), cell(SHEET, "I410"), cell(SHEET, "G407"), cell(SHEET, "I410"), cell(SHEET, "H407")); };
SHEET_DATA["Данные взрослой матрицы"].formulas["K407"] = function(SHEET, cell, rangeVals) { return fn_IFERROR(function(){ return fn_VLOOKUP(cell(SHEET, "J407"), rangeVals(SHEET, "A404", "B483"), 2, false); }, ""); };
